using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appBuilder = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName, EvaluationScenario scenario)
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>();
        ChatResponse? response = null;

        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(ChatRole.User, turn.Content));
            response = await chatClient.GetResponseAsync(messages);
            messages.Add(response.Message);
        }

        Assert.IsNotNull(response, $"No response received for scenario '{scenarioName}'.");

        var evaluator = CreateEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response);

        foreach (var assertion in scenario.Assertions)
        {
            var metric = result.Metrics.FirstOrDefault(m =>
                m.Name.Equals(assertion.Metric, StringComparison.OrdinalIgnoreCase));

            Assert.IsNotNull(metric, $"Metric '{assertion.Metric}' not found in scenario '{scenarioName}'.");

            if (metric is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= assertion.Threshold,
                    $"Scenario '{scenarioName}': metric '{assertion.Metric}' scored {numeric.Value}, " +
                    $"expected >= {assertion.Threshold}.");
            }
        }
    }

    private static ChatConfiguration CreateEvaluator()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ChatConfiguration(evaluators);
    }

    private static IEnumerable<object[]> GetScenarios()
    {
        var config = EvaluationScenario.LoadFromYaml(
            Path.Combine(AppContext.BaseDirectory, "evaluation.yml"));

        foreach (var scenario in config)
        {
            yield return new object[] { scenario.Name, scenario };
        }
    }
}

using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

public class EvaluationScenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<TurnDefinition> Turns { get; set; } = [];
    public List<AssertionDefinition> Assertions { get; set; } = [];

    public static List<EvaluationScenario> LoadFromYaml(string path)
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(HyphenatedNamingConvention.Instance)
            .Build();

        var config = deserializer.Deserialize<EvaluationConfig>(yaml);
        return config.Scenarios;
    }
}

public class EvaluationConfig
{
    public List<EvaluationScenario> Scenarios { get; set; } = [];
}

public class TurnDefinition
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
}

public class AssertionDefinition
{
    public string Metric { get; set; } = string.Empty;
    public double Threshold { get; set; }
}

